    animate() {

        for (var i = 0; i < this.animatedSprites.length; i++) {

            if (this.animatedSprites !== null) {

                var a = this.animatedSprites[i];

                if (a.aniCount === undefined) {
                    a.aniCount = 0;
                    a.curFrame = 0;
                }

                if (a.aniSpeed === undefined) {
                    a.aniSpeed = .25;
                }

                if (a.ani === undefined) {
                    a.ani = [];
                }

                a.aniCount += this.e.dt;

                if (a.aniCount > a.aniSpeed) {

                    a.aniCount = 0;
                    a.curFrame += 1;

                    if (a.curFrame >= a.ani.length && a.aniLoop!==false) {
                        a.curFrame = 0;
                    }

                    // console.log(a.curFrame)

                    if(a.isSprite===true){
                        a.map = a.ani[a.curFrame];
                    }else{
                        a.texture = a.ani[a.curFrame];
                    }

                }

            }

        }

    }

    buttonConverter(){

        if(this.bcAction==="set"){

            for(var i=0; i<this.buttonConversions.length; i++){

                var buttonObject = new Object;
                buttonObject.pixiBut = this.buttonConversions[i];
                buttonObject.link = this.buttonConversions[i].link;

                buttonObject.htmlBut = document.createElement("div");
                buttonObject.htmlBut.style.position = "fixed"
                buttonObject.htmlBut.style.backgroundColor = "blue"
                buttonObject.htmlBut.style.opacity = "0"
                buttonObject.htmlBut.style.zIndex = "10000"
                buttonObject.htmlBut.style.cursor = "pointer"

                document.body.appendChild(buttonObject.htmlBut);

                console.log(">>>>>>>>>>>>"+buttonObject.link)
                // console.log("")

                this.convertButtons.push(buttonObject);

            }

            this.bcCount = 0
            this.bcAction = "assign"

        }else if(this.bcAction==="assign"){

            console.log("asssign "+this.bcCount)

            var o = this.convertButtons[this.bcCount];

            o.htmlBut.addEventListener("mousedown", event => {

                window.open(o.link, '_blank');
                this.convertLink(o);
                this.e.killDrag=1;

            });

            o.htmlBut.addEventListener("touchstart", event => {

                window.open(o.link, '_blank');
                this.convertLink(o);
                this.e.killDrag=1;

            });

            this.bcCount+=1;

            if(this.bcCount>=this.convertButtons.length){

                this.bcAction="handle"

            }

        }else if(this.bcAction==="handle"){

            for(var i=0; i<this.convertButtons.length; i++){

                var o = this.convertButtons[i];
                var p = this.convertButtons[i].pixiBut;
                var h = this.convertButtons[i].htmlBut;

                h.style.left = p.getGlobalPosition().x-(p.getBounds().width/2)+"px";
                h.style.top = p.getGlobalPosition().y-(p.getBounds().height/2)+"px";
                h.style.width = p.getBounds().width+"px";
                h.style.height = p.getBounds().height+"px";

                // console.log(i+" / "+p.buttonMode+" / "+p.interactive)

                // if(p.buttonMode===true && p.interactive===true){
                if(p.buttonMode===true ){

                    h.style.display="inline";

                }else{

                    h.style.display="none";

                }

                // console.log(h.style.display);
                // console.log("------------");

            }

        }



    }


